int wifi_manager_scan(wifi_ap_t *aps, int max)
{
  posix_spawn_file_actions_t fa;
  char *argv[4];
  pid_t pid;
  int ret;
  int status;

  if (aps == NULL || max <= 0)
    {
      return -EINVAL;
    }

  if (!g_initialized)
    {
      return -ENODEV;
    }

  posix_spawn_file_actions_init(&fa);

  /* wapi 没有可链接的 C API → 跑 CLI 并把 stdout 重定向到文件再解析 */

  posix_spawn_file_actions_addopen(&fa, 1, WIFI_SCAN_OUT,
                                   O_WRONLY | O_CREAT | O_TRUNC, 0644);

  argv[0] = "wapi";
  argv[1] = "scan";
  argv[2] = "wlan0";
  argv[3] = NULL;

  ret = posix_spawn(&pid, "wapi", &fa, NULL, argv, NULL);
  posix_spawn_file_actions_destroy(&fa);

  if (ret != 0)
    {
      printf("[WIFI] 扫描启动失败: %d\n", ret);
      return -ret;
    }

  waitpid(pid, &status, 0);

  ret = wifi_parse_scan(WIFI_SCAN_OUT, aps, max);

  /* ⚠ 换环境时的典型故障：SD 上存的还是旧网络，开机自动连接失败后
   * esp32 停在 "STA is connecting"，此时 wapi scan 被拒
   * （"STA is connecting, scan are not allowed"）→ 一个网络都扫不到，
   * 用户就没法改用新网络。这里先断开让 STA 回到空闲态，再扫一次。 */

  if (ret <= 0)
    {
      printf("[WIFI] 扫描到 %d 个，先断开再重试一次\n", ret);

      argv[0] = "wapi";
      argv[1] = "disconnect";
      argv[2] = "wlan0";
      argv[3] = NULL;

      if (posix_spawn(&pid, "wapi", NULL, NULL, argv, NULL) == 0)
        {
          waitpid(pid, &status, 0);
        }

      usleep(800 * 1000);

      posix_spawn_file_actions_init(&fa);
      posix_spawn_file_actions_addopen(&fa, 1, WIFI_SCAN_OUT,
                                       O_WRONLY | O_CREAT | O_TRUNC, 0644);

      argv[0] = "wapi";
      argv[1] = "scan";
      argv[2] = "wlan0";
      argv[3] = NULL;

      if (posix_spawn(&pid, "wapi", &fa, NULL, argv, NULL) == 0)
        {
          posix_spawn_file_actions_destroy(&fa);
          waitpid(pid, &status, 0);
          ret = wifi_parse_scan(WIFI_SCAN_OUT, aps, max);
        }
      else
        {
          posix_spawn_file_actions_destroy(&fa);
        }
    }

  return ret;
}

