547 int wifi_manager_scan(wifi_ap_t *aps, int max)
548 {
549   posix_spawn_file_actions_t fa;
550   char *argv[4];
551   pid_t pid;
552   int ret;
553   int status;
554 
555   if (aps == NULL || max <= 0)
556     {
557       return -EINVAL;
558     }
559 
560   if (!g_initialized)
561     {
562       return -ENODEV;
563     }
564 
565   posix_spawn_file_actions_init(&fa);
566 
567   /* wapi 没有可链接的 C API → 跑 CLI 并把 stdout 重定向到文件再解析 */
568 
569   posix_spawn_file_actions_addopen(&fa, 1, WIFI_SCAN_OUT,
570                                    O_WRONLY | O_CREAT | O_TRUNC, 0644);
571 
572   argv[0] = "wapi";
573   argv[1] = "scan";
574   argv[2] = "wlan0";
575   argv[3] = NULL;
576 
577   ret = posix_spawn(&pid, "wapi", &fa, NULL, argv, NULL);
578   posix_spawn_file_actions_destroy(&fa);
579 
580   if (ret != 0)
581     {
582       printf("[WIFI] 扫描启动失败: %d\n", ret);
583       return -ret;
584     }
585 
586   waitpid(pid, &status, 0);
587 
588   ret = wifi_parse_scan(WIFI_SCAN_OUT, aps, max);
589 
590   /* ⚠ 换环境时的典型故障：SD 上存的还是旧网络，开机自动连接失败后
591    * esp32 停在 "STA is connecting"，此时 wapi scan 被拒
592    * （"STA is connecting, scan are not allowed"）→ 一个网络都扫不到，
593    * 用户就没法改用新网络。这里先断开让 STA 回到空闲态，再扫一次。 */
594 
595   if (ret <= 0)
596     {
597       printf("[WIFI] 扫描到 %d 个，先断开再重试一次\n", ret);
598 
599       argv[0] = "wapi";
600       argv[1] = "disconnect";
601       argv[2] = "wlan0";
602       argv[3] = NULL;
603 
604       if (posix_spawn(&pid, "wapi", NULL, NULL, argv, NULL) == 0)
605         {
606           waitpid(pid, &status, 0);
607         }
608 
609       usleep(800 * 1000);
610 
611       posix_spawn_file_actions_init(&fa);
612       posix_spawn_file_actions_addopen(&fa, 1, WIFI_SCAN_OUT,
613                                        O_WRONLY | O_CREAT | O_TRUNC, 0644);
614 
615       argv[0] = "wapi";
616       argv[1] = "scan";
617       argv[2] = "wlan0";
618       argv[3] = NULL;
619 
620       if (posix_spawn(&pid, "wapi", &fa, NULL, argv, NULL) == 0)
621         {
622           posix_spawn_file_actions_destroy(&fa);
623           waitpid(pid, &status, 0);
624           ret = wifi_parse_scan(WIFI_SCAN_OUT, aps, max);
625         }
626       else
627         {
628           posix_spawn_file_actions_destroy(&fa);
629         }
630     }
631 
632   return ret;
633 }
